import { SegmentedControl } from '@kerfjs/ui/segmented-control';

type WorkspaceView = 'board' | 'list' | 'timeline';
type Props = { value: WorkspaceView; dispatch: (action: { type: 'workspace.view.changed'; value: WorkspaceView }) => void };

const options = [
  { value: 'board', label: 'Board' },
  { value: 'list', label: 'List' },
  { value: 'timeline', label: 'Timeline' }
] as const;

export function WorkspaceViewChoice({ value, dispatch }: Props) {
  return (
    <SegmentedControl
      aria-label="Workspace view"
      value={value}
      options={options}
      onValueChange={(next: WorkspaceView) => dispatch({ type: 'workspace.view.changed', value: next })}
    />
  );
}
